<?php declare(strict_types=1); header('Content-Type: application/json; charset=utf-8');header('Cache-Control:no-store');function out($x,$s=200){http_response_code($s);echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}try{$world=(string)($_GET['world']??'GW001');if(!preg_match('/^GW00[1-9]$|^GW010$/D',$world))out(['ok'=>false,'error'=>'invalid_world'],422);$resource=(string)($_GET['resource']??'context');$base=dirname(__DIR__).'/nexus/public/';require_once $base.'core.php';require_once $base.'hub.php';$config=require dirname(__DIR__).'/__imc_private_gateway/config.php';$cfg=$config['db'];$family=in_array($world,['GW002','GW003','GW007','GW008'],true)?'gold':'custom';$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$cfg['host'],$cfg['port'],$cfg[$family]),$cfg['user'],$cfg['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$core=nexus_core_db($cfg);if($resource==='context'){out(['ok'=>true,'world'=>$world,'seasons'=>nexus_core_rows($core,'SELECT imc_season,imc_season_start_date,imc_season_end_date FROM `IMC Game World Season` WHERE game_world_id=? ORDER BY imc_season DESC',[$world])]);}if($resource==='catalog')out(['ok'=>true,'rows'=>nexus_catalog($pdo,$core,$world,nexus_season($core,$world,(string)($_GET['season']??'')))]);if($resource==='competition')out(nexus_hub($pdo,$core,$world));$allowed=['results','schedule','transfers','players'];if(!in_array($resource,$allowed,true))out(['ok'=>false,'error'=>'invalid_resource'],422);$_GET['world']=$world;$_GET['resource']=$resource;ob_start();include $base.'data.php';}catch(Throwable $e){out(['ok'=>false,'error'=>'data_unavailable'],500);}